<?php
namespace App\Http\Controllers\Api;
use App\Contracts\PaymentGateway; use App\Http\Controllers\Controller; use App\Models\Address; use App\Models\CartItem; use App\Models\DiscountCode; use App\Models\Order; use App\Models\Payment; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class CheckoutController extends Controller {
 public function options(Request $r){$subtotal=$this->subtotal($r->user()->id);return ['addresses'=>Address::where('user_id',$r->user()->id)->latest('is_default')->get(),'shipping_methods'=>DB::table('shipping_methods')->where('is_active',true)->get()->map(function($m)use($subtotal){$m->calculated_cost=$m->free_threshold&&$subtotal>=$m->free_threshold?0:$m->base_cost;return $m;}),'delivery_slots'=>DB::table('delivery_slots')->where('is_active',true)->whereDate('date','>=',today())->whereColumn('reserved','<','capacity')->orderBy('date')->orderBy('starts_at')->get()];}
 public function discount(Request $r){$data=$r->validate(['code'=>'required|string']);$subtotal=$this->subtotal($r->user()->id);$discount=$this->validDiscount($data['code'],$r->user()->id,$subtotal);return ['title'=>$discount->title,'amount'=>$discount->calculate($subtotal),'subtotal'=>$subtotal];}
 public function store(Request $r,PaymentGateway $gateway){$data=$r->validate(['address_id'=>'required|exists:addresses,id','shipping_method_id'=>'required|exists:shipping_methods,id','delivery_slot_id'=>'nullable|exists:delivery_slots,id','discount_code'=>'nullable|string','customer_note'=>'nullable|string|max:500']);$user=$r->user();$result=DB::transaction(function()use($data,$user){$address=Address::where('user_id',$user->id)->findOrFail($data['address_id']);$shipping=DB::table('shipping_methods')->where('is_active',true)->find($data['shipping_method_id']);abort_unless($shipping,422,'روش ارسال معتبر نیست.');$items=CartItem::where('user_id',$user->id)->with('variant.product')->lockForUpdate()->get();if($items->isEmpty())throw ValidationException::withMessages(['cart'=>'سبد خرید خالی است.']);foreach($items as $item)if(!$item->variant->is_active||$item->variant->stock<$item->quantity)throw ValidationException::withMessages(['cart'=>'موجودی یکی از محصولات تغییر کرده است.']);$subtotal=$items->sum(fn($x)=>$x->variant->price*$x->quantity);$discount=!empty($data['discount_code'])?$this->validDiscount($data['discount_code'],$user->id,$subtotal):null;$discountAmount=$discount?->calculate($subtotal)??0;$shippingAmount=$shipping->free_threshold&&$subtotal>=$shipping->free_threshold?0:$shipping->base_cost;if($data['delivery_slot_id']){$slot=DB::table('delivery_slots')->lockForUpdate()->find($data['delivery_slot_id']);abort_unless($slot&&$slot->is_active&&$slot->reserved<$slot->capacity,422,'بازه ارسال تکمیل شده است.');$shippingAmount+=$slot->extra_cost;DB::table('delivery_slots')->where('id',$slot->id)->increment('reserved');}$order=Order::create(['number'=>(string)Str::uuid(),'user_id'=>$user->id,'address_id'=>$address->id,'shipping_method_id'=>$shipping->id,'delivery_slot_id'=>$data['delivery_slot_id'],'discount_code_id'=>$discount?->id,'subtotal'=>$subtotal,'discount_amount'=>$discountAmount,'shipping_amount'=>$shippingAmount,'payable_amount'=>$subtotal-$discountAmount+$shippingAmount,'address_snapshot'=>$address->toArray(),'customer_note'=>$data['customer_note']??null]);foreach($items as $item){$v=$item->variant;$before=$v->stock;$order->items()->create(['product_id'=>$v->product_id,'variant_id'=>$v->id,'title'=>$v->product->title,'sku'=>$v->sku,'attributes'=>$v->attributes,'unit_price'=>$v->price,'quantity'=>$item->quantity,'total'=>$v->price*$item->quantity]);$v->decrement('stock',$item->quantity);DB::table('inventory_movements')->insert(['variant_id'=>$v->id,'user_id'=>$user->id,'quantity'=>-$item->quantity,'stock_before'=>$before,'stock_after'=>$before-$item->quantity,'reason'=>'sale','note'=>'سفارش '.$order->number,'created_at'=>now(),'updated_at'=>now()]);}if($discount){DB::table('discount_redemptions')->insert(['discount_code_id'=>$discount->id,'user_id'=>$user->id,'order_id'=>$order->id,'amount'=>$discountAmount,'created_at'=>now(),'updated_at'=>now()]);$discount->increment('used_count');}DB::table('order_status_histories')->insert(['order_id'=>$order->id,'user_id'=>$user->id,'to_status'=>'pending','note'=>'ثبت سفارش','created_at'=>now(),'updated_at'=>now()]);CartItem::where('user_id',$user->id)->delete();$payment=$order->payments()->create(['gateway'=>'zarinpal','amount'=>$order->payable_amount,'status'=>'pending']);return compact('order','payment');});$url=$gateway->request($result['payment'],url('/api/v1/payment/callback/'.$result['payment']->id));return response()->json(['order'=>$result['order']->load('items'),'payment_url'=>$url],201);}
 public function callback(Request $r,Payment $payment,PaymentGateway $gateway){if($payment->status==='paid')return redirect(config('app.frontend_url','http://localhost:3001').'/payment/success?order='.$payment->order_id);try{$ref=$gateway->verify($payment,$r->all());$payment->order()->update(['payment_status'=>'paid','status'=>'confirmed']);DB::table('order_status_histories')->insert(['order_id'=>$payment->order_id,'from_status'=>'pending','to_status'=>'confirmed','note'=>'پرداخت موفق: '.$ref,'created_at'=>now(),'updated_at'=>now()]);return redirect(config('app.frontend_url','http://localhost:3001').'/payment/success?order='.$payment->order_id);}catch(\Throwable $e){$payment->update(['status'=>'failed']);return redirect(config('app.frontend_url','http://localhost:3001').'/payment/failed?message='.urlencode($e->getMessage()));}}
 private function subtotal(int $userId):int{return (int)CartItem::where('user_id',$userId)->with('variant')->get()->sum(fn($x)=>$x->variant->price*$x->quantity);}
 private function validDiscount(string $code,int $userId,int $subtotal):DiscountCode{$d=DiscountCode::whereRaw('UPPER(code)=?',[mb_strtoupper($code)])->first();$used=$d?DB::table('discount_redemptions')->where('discount_code_id',$d->id)->where('user_id',$userId)->count():0;if(!$d||!$d->is_active||($d->starts_at&&$d->starts_at->isFuture())||($d->expires_at&&$d->expires_at->isPast())||($d->usage_limit&&$d->used_count>=$d->usage_limit)||$used>=$d->per_user_limit||$subtotal<$d->min_order_amount)throw ValidationException::withMessages(['code'=>'کد تخفیف معتبر یا قابل استفاده نیست.']);return $d;}
}
